import { randomUUID } from 'node:crypto';
import { CheckCircle2, FileWarning, ShieldCheck } from 'lucide-react';
import { AdminTablePaginationFooter } from '../../components/admin-data-table';

import { AdminFilterChipGroup } from '../../components/admin-filter-chip-group';
import { AdminFilterPanel } from '../../components/admin-filter-panel';
import { AdminFilterSummary } from '../../components/admin-filter-summary';
import {
  AdminFinanceOperatorEvidence,
  type AdminFinanceOperatorEvidenceLine,
} from '../../components/admin-finance-operator-evidence';
import {
  AdminFormControlButton,
  AdminFormControlLink,
  AdminFormGrid,
  AdminFormInput,
  AdminFormSelect,
  AdminFormShell,
  AdminFormTextarea,
} from '../../components/admin-form-controls';
import { AdminInlineFallback } from '../../components/admin-inline-fallback';
import { AdminPageTemplate } from '../../components/admin-page-template';
import { AdminStageItem, AdminStageList } from '../../components/admin-stage-item';
import { AdminNoticeCard, AdminSection } from '../../components/admin-surface';
import { AdminTablePanel } from '../../components/admin-table-panel';
import { AdminTextLink } from '../../components/admin-text-link';
import { DateTimeText } from '../../components/date-time-text';
import { MoneyText } from '../../components/money-text';
import { StatusBadge } from '../../components/status-badge';
import type {
  AdminManualWalletAdjustmentDirection,
  AdminManualWalletAdjustmentOwnerType,
  AdminManualWalletAdjustmentOwnerOption,
  AdminManualWalletAdjustmentPreview,
  AdminManualWalletAdjustmentRequest,
  AdminManualWalletAdjustmentRequestStatus,
  AdminManualWalletAdjustmentRow,
  AdminManualWalletAdjustmentSummary,
  AdminManualWalletAdjustmentType,
} from '../../lib/admin-api';
import { adminGet, adminPost } from '../../lib/admin-api';
import { FinanceDataTable } from '../finance-tax/finance-data-table';
import { createManualWalletAdjustment } from './actions';

type WalletAdjustmentsPageProps = {
  readonly searchParams?: Promise<Record<string, string | string[] | undefined>>;
};

const ownerOptions: Array<{ label: string; value: AdminManualWalletAdjustmentOwnerType }> = [
  { label: 'Partner wallet', value: 'PARTNER' },
  { label: 'Customer wallet', value: 'CUSTOMER' },
];

const directionOptions: Array<{ label: string; value: AdminManualWalletAdjustmentDirection }> = [
  { label: 'Credit wallet', value: 'CREDIT' },
  { label: 'Debit wallet', value: 'DEBIT' },
];

const adjustmentTypeOptions: Array<{ label: string; value: AdminManualWalletAdjustmentType }> = [
  { label: 'Promotion credit', value: 'PROMOTION_CREDIT' },
  { label: 'Customer compensation', value: 'CUSTOMER_COMPENSATION' },
  { label: 'Partner bonus', value: 'PARTNER_BONUS' },
  { label: 'Referral correction', value: 'REFERRAL_CORRECTION' },
  { label: 'Error correction', value: 'ERROR_CORRECTION' },
  { label: 'Penalty', value: 'PENALTY' },
  { label: 'Receivable write-off', value: 'RECEIVABLE_WRITE_OFF' },
  { label: 'Manual reversal', value: 'MANUAL_REVERSAL' },
  { label: 'Cash booking deduction - blocked here', value: 'CASH_BOOKING_DEDUCTION' },
];
const WALLET_ADJUSTMENT_HISTORY_TAKE = 10;
const WALLET_ADJUSTMENT_HISTORY_MAX_TAKE = 50;
const WALLET_ADJUSTMENT_REQUEST_HISTORY_TAKE = 10;
const WALLET_ADJUSTMENT_REQUEST_HISTORY_MAX_TAKE = 50;
const requestStatusOptions: Array<{
  label: string;
  value: AdminManualWalletAdjustmentRequestStatus | '';
}> = [
  { label: 'All request statuses', value: '' },
  { label: 'Pending approval', value: 'REQUESTED' },
  { label: 'Executed', value: 'EXECUTED' },
  { label: 'Rejected', value: 'REJECTED' },
  { label: 'Cancelled', value: 'CANCELLED' },
];

export default async function WalletAdjustmentsPage({ searchParams }: WalletAdjustmentsPageProps) {
  const params = searchParams ? await searchParams : {};
  const formState = readWalletAdjustmentFormState(params);
  const historyFilters = readWalletAdjustmentHistoryFilters(params);
  const requestHistoryFilters = readWalletAdjustmentRequestHistoryFilters(params);
  const notice = walletAdjustmentNotice(readParam(params, 'adjustmentNotice'));
  const ownerCandidates = await fetchWalletAdjustmentOwners(formState);
  const selectedOwner = ownerCandidates.find(
    (owner) => owner.ownerId === formState.ownerId && owner.ownerType === formState.ownerType,
  );
  const [preview, adjustmentRows, adjustmentSummary, requestRows, requestSummary] = await Promise.all([
    formState.intent === 'preview' && selectedOwner ? fetchPreview(formState) : Promise.resolve(null),
    fetchAdjustmentHistory(formState, historyFilters),
    fetchAdjustmentHistorySummary(formState, historyFilters),
    fetchAdjustmentRequestHistory(formState, requestHistoryFilters),
    fetchAdjustmentRequestHistorySummary(formState, requestHistoryFilters),
  ]);
  const currency = preview?.currency ?? 'VND';
  const adjustmentTotal = walletAdjustmentSummaryTotal(adjustmentSummary);
  const requestTotal = walletAdjustmentSummaryTotal(requestSummary);
  const historyPagination = buildWalletAdjustmentHistoryPagination(
    adjustmentRows,
    historyFilters,
    adjustmentTotal,
  );
  const requestHistoryPagination = buildWalletAdjustmentRequestHistoryPagination(
    requestRows,
    requestHistoryFilters,
    requestTotal,
  );

  return (
    <AdminPageTemplate
      description="Create an approval-controlled wallet adjustment and inspect immutable wallet and accounting records on one page. Manual adjustments never move bank or cash accounts."
      title="Wallet Adjustments"
    >
      {notice ? (
        <AdminNoticeCard
          className="admin-mb-16"
          role="status"
          tone={notice.tone === 'success' ? 'success' : 'danger'}
        >
          <div>
            <h2>{notice.title}</h2>
            <p className="muted">{notice.detail}</p>
          </div>
          <StatusBadge tone={notice.tone}>{notice.badge}</StatusBadge>
        </AdminNoticeCard>
      ) : null}

        <AdminSection
        description="Find and verify one customer or partner, preview the balance and accounting impact, then submit a persistent request for a separate finance approver."
          statusLabel={preview ? 'Preview ready' : 'Preview required'}
          statusTone={preview ? 'success' : 'warning'}
          title="Manual adjustment request"
        >
          <AdminFormGrid method="get">
          <input name="intent" type="hidden" value="search" />
            <AdminFormSelect
              defaultValue={formState.ownerType}
              label="Wallet owner type"
              name="ownerType"
              options={ownerOptions}
            />
            <AdminFormInput
            defaultValue={formState.ownerSearch}
            label="Customer or partner"
            minLength={2}
            name="ownerSearch"
            placeholder="Name or phone"
              required
            type="search"
            />
          <AdminFormControlButton>Find wallet owner</AdminFormControlButton>
        </AdminFormGrid>

        {formState.ownerSearch ? (
          <WalletOwnerSearchResults candidates={ownerCandidates} formState={formState} />
        ) : null}

        {selectedOwner ? (
          <>
            <SelectedWalletOwner owner={selectedOwner} />
            <AdminFormGrid method="get">
              <input name="intent" type="hidden" value="preview" />
              <input name="ownerId" type="hidden" value={selectedOwner.ownerId} />
              <input name="ownerSearch" type="hidden" value={formState.ownerSearch} />
              <input name="ownerType" type="hidden" value={selectedOwner.ownerType} />
            <AdminFormSelect
              defaultValue={formState.direction}
              label="Adjustment direction"
              name="direction"
              options={directionOptions}
            />
            <AdminFormSelect
              defaultValue={formState.adjustmentType}
              label="Adjustment type"
              name="adjustmentType"
              options={adjustmentTypeOptions}
            />
            <AdminFormInput
              defaultValue={formState.amount}
              label="Amount"
              min={1}
              name="amount"
              placeholder="Amount in VND"
              required
              step={1}
              type="number"
            />
            <AdminFormInput
              defaultValue={formState.monthlyPeriod}
              label="Monthly period"
              name="monthlyPeriod"
              placeholder="YYYY-MM"
            />
            <AdminFormInput
              defaultValue={formState.attachmentUrl}
              label="Attachment URL"
              name="attachmentUrl"
              placeholder="Evidence URL for high-risk adjustments"
            />
            <AdminFormTextarea
              className="admin-grid-span-2"
              defaultValue={formState.reason}
              label="Reason"
              name="reason"
              placeholder="Operational reason visible in audit log"
              required
              rows={3}
            />
            <AdminFormControlButton>Preview accounting</AdminFormControlButton>
          </AdminFormGrid>
          </>
        ) : null}
          <AdminFilterSummary
            ariaLabel="Active wallet adjustment request filters"
          labels={walletAdjustmentRequestLabels(formState, selectedOwner)}
            tone="info"
          />
          <AdjustmentPolicyChecklist />
        </AdminSection>

      <AdminFilterPanel
        className="admin-mb-16"
        description="Review the approval lifecycle separately from executed wallet ledger entries. Cancelled and rejected requests never appear as wallet movement."
        resultLabel={`${requestTotal} matching request(s)`}
        resultTone={requestTotal > 0 ? 'info' : 'warning'}
        title="Request history filters"
      >
        <AdminFormGrid method="get">
          <input name="view" type="hidden" value="requests" />
          <AdminFormSelect
            defaultValue={requestHistoryFilters.status ?? ''}
            label="Request status"
            name="requestStatus"
            options={requestStatusOptions}
          />
          <AdminFormSelect
            defaultValue={walletAdjustmentRequestHistoryOwnerType(formState, requestHistoryFilters) ?? ''}
            label="Wallet owner"
            name="ownerType"
            options={[{ label: 'All wallet owners', value: '' }, ...ownerOptions]}
          />
          <AdminFormSelect
            defaultValue={String(requestHistoryFilters.pageSize)}
            label="Rows per page"
            name="requestPageSize"
            options={[
              { label: '10 rows', value: '10' },
              { label: '25 rows', value: '25' },
              { label: '50 rows', value: '50' },
            ]}
          />
          <AdminFormControlButton>Apply request filters</AdminFormControlButton>
        </AdminFormGrid>
        <AdminFilterSummary
          ariaLabel="Active wallet adjustment request history filters"
          labels={walletAdjustmentRequestHistoryFilterLabels(formState, requestHistoryFilters)}
          tone="info"
        />
      </AdminFilterPanel>

      <AdminTablePanel
        description="Request records show maker and decision evidence. Only Executed requests have a linked immutable wallet ledger entry."
        resultLabel={`${requestTotal} total`}
        resultTone={requestTotal > 0 ? 'info' : 'warning'}
        title="Adjustment request history"
      >
        <FinanceDataTable
          emptyMessage="No manual wallet adjustment requests found for this filter."
          headers={['Requested', 'Owner', 'Adjustment', 'Amount and balance', 'Status', 'Decision']}
          rowCount={requestHistoryPagination.rows.length}
        >
          {requestHistoryPagination.rows.map((request) => (
            <tr key={request.id}>
              <td>
                <strong>
                  <DateTimeText value={request.createdAt} />
                </strong>
                <p className="muted">{request.id}</p>
              </td>
              <td>
                <strong>
                  <AdminTextLink href={walletOwnerDetailHref(request.ownerType, request.ownerId)}>
                    {request.ownerName ?? request.ownerId}
                  </AdminTextLink>
                </strong>
                <p className="muted">{request.ownerType}</p>
              </td>
              <td>
                <StatusBadge tone={request.direction === 'CREDIT' ? 'success' : 'warning'}>
                  {request.direction}
                </StatusBadge>
                <p className="muted admin-mt-6">{request.adjustmentType}</p>
                <p>{request.reason}</p>
              </td>
              <td>
                <strong>
                  <MoneyText amount={request.amount} currency={request.currency} />
                </strong>
                <p className="muted">
                  <MoneyText amount={request.requestedBeforeBalance} currency={request.currency} /> -&gt;{' '}
                  <MoneyText amount={request.requestedAfterBalance} currency={request.currency} />
                </p>
              </td>
              <td>
                <StatusBadge tone={walletAdjustmentRequestStatusTone(request.status)}>
                  {walletAdjustmentRequestStatusLabel(request.status)}
                </StatusBadge>
                <p className="muted admin-mt-6">
                  Updated <DateTimeText value={request.updatedAt ?? request.createdAt} />
                </p>
                {request.ledgerEntryId ? (
                  <p className="muted">Ledger linked</p>
                ) : (
                  <AdminInlineFallback>No wallet ledger write</AdminInlineFallback>
                )}
              </td>
              <td>
                <AdminFinanceOperatorEvidence lines={walletAdjustmentRequestOperatorLines(request)} />
                {request.decisionReason ? (
                  <p>{request.decisionReason}</p>
                ) : request.status === 'REQUESTED' ? (
                  <AdminInlineFallback>Awaiting decision</AdminInlineFallback>
                ) : request.status === 'EXECUTED' ? (
                  <p className="muted">Approval completed</p>
                ) : (
                  <AdminInlineFallback>No decision reason stored</AdminInlineFallback>
                )}
                {request.attachmentUrl ? (
                  <p className="muted">Attachment saved</p>
                ) : request.requiresAttachment ? (
                  <AdminInlineFallback>Required attachment unavailable</AdminInlineFallback>
                ) : (
                  <p className="muted">Attachment not required</p>
                )}
              </td>
            </tr>
          ))}
        </FinanceDataTable>
        <AdminTablePaginationFooter
          activePage={requestHistoryPagination.page}
          ariaLabel="Manual wallet adjustment request history pages"
          from={requestHistoryPagination.from}
          hrefForPage={(page) =>
            walletAdjustmentRequestHistoryPageHref(formState, historyFilters, requestHistoryFilters, page)
          }
          to={requestHistoryPagination.to}
          totalPages={requestHistoryPagination.totalPages}
          totalRows={requestHistoryPagination.totalRows}
        />
      </AdminTablePanel>

          <AdminFilterPanel
            className="admin-mb-16"
            description="Filter immutable manual adjustment ledger entries by wallet owner. Results stay server paginated and do not load account balances or unrelated finance evidence."
            resultLabel={`${adjustmentTotal} matching record(s)`}
            resultTone={adjustmentTotal > 0 ? 'info' : 'warning'}
            title="Record filters"
          >
            <AdminFormGrid method="get">
              <input name="view" type="hidden" value="records" />
              <AdminFormSelect
                defaultValue={walletAdjustmentHistoryOwnerType(formState, historyFilters) ?? ''}
                label="Wallet owner"
                name="ownerType"
                options={[{ label: 'All wallet owners', value: '' }, ...ownerOptions]}
              />
              <AdminFormSelect
                defaultValue={String(historyFilters.pageSize)}
                label="Rows per page"
                name="pageSize"
                options={[
                  { label: '10 rows', value: '10' },
                  { label: '25 rows', value: '25' },
                  { label: '50 rows', value: '50' },
                ]}
              />
              <AdminFormControlButton>Apply filters</AdminFormControlButton>
            </AdminFormGrid>
            <AdminFilterSummary
              ariaLabel="Active wallet adjustment record filters"
              labels={walletAdjustmentRecordFilterLabels(formState, historyFilters)}
              tone="info"
            />
          </AdminFilterPanel>

          <AdminTablePanel
            description={
          selectedOwner
            ? `Showing recent manual wallet adjustments for ${selectedOwner.displayName}.`
                : historyFilters.ownerType
                  ? `Showing manual wallet adjustments for ${optionLabel(ownerOptions, historyFilters.ownerType).toLowerCase()} records.`
              : 'Showing the latest manual wallet adjustments. Find and select an owner above to narrow the records.'
            }
            resultLabel={`${adjustmentTotal} total`}
            resultTone={adjustmentTotal > 0 ? 'info' : 'warning'}
            title="Manual adjustment history"
          >
            <FinanceDataTable
              emptyMessage="No manual wallet adjustment ledger rows found for this filter."
              headers={['Created', 'Owner', 'Adjustment', 'Amount', 'Approval', 'Balance', 'Reason']}
              rowCount={historyPagination.rows.length}
            >
              {historyPagination.rows.map((row) => (
                <tr key={row.id}>
                  <td>
                    <strong>
                      <DateTimeText value={row.createdAt} />
                    </strong>
                    <p className="muted">{row.ledgerType}</p>
                  </td>
                  <td>
                <strong>
                  <AdminTextLink href={walletOwnerDetailHref(row.ownerType, row.ownerId)}>
                    {row.ownerLabel}
                  </AdminTextLink>
                </strong>
                    <p className="muted">{row.ownerType}</p>
                  </td>
                  <td>
                    <StatusBadge tone={row.direction === 'CREDIT' ? 'success' : 'warning'}>
                      {row.direction}
                    </StatusBadge>
                    <p className="muted admin-mt-6">{row.adjustmentType}</p>
                  </td>
                  <td>
                    <strong>
                      <MoneyText amount={row.amount} currency={row.currency} />
                    </strong>
                    <p className="muted">
                      Delta <MoneyText amount={row.walletDelta} currency={row.currency} />
                    </p>
                  </td>
                  <td>
                    {row.approvalId ? (
                      <strong>{row.approvalId}</strong>
                    ) : (
                      <AdminInlineFallback>Missing approval</AdminInlineFallback>
                    )}
                    <AdminFinanceOperatorEvidence
                      lines={[
                        {
                          fallbackId: row.requestedByAdminId,
                          key: 'requested-by',
                          label: 'Requested by',
                          operator: row.requestedBy,
                        },
                        {
                          fallbackId: row.approvalAdminId,
                          key: 'approved-by',
                          label: 'Approved by',
                          operator: row.approvalAdmin,
                        },
                      ]}
                    />
                    {!row.approvalAdminId ? (
                  <AdminInlineFallback className="admin-mt-6">Approving admin not stored</AdminInlineFallback>
                    ) : null}
                    {row.attachmentUrl ? (
                      <p className="muted">Attachment saved</p>
                    ) : (
                      <AdminInlineFallback className="admin-mt-6">No attachment</AdminInlineFallback>
                    )}
                  </td>
                  <td>
                    <strong>{formatBalanceChange(row)}</strong>
                    <p className="muted">{walletImpactLabel(row)}</p>
                  </td>
              <td>{row.reason ? row.reason : <AdminInlineFallback>No reason stored</AdminInlineFallback>}</td>
                </tr>
              ))}
            </FinanceDataTable>
            <AdminTablePaginationFooter
              activePage={historyPagination.page}
              ariaLabel="Manual wallet adjustment history pages"
              from={historyPagination.from}
              hrefForPage={(page) => walletAdjustmentHistoryPageHref(formState, historyFilters, page)}
              to={historyPagination.to}
              totalPages={historyPagination.totalPages}
              totalRows={historyPagination.totalRows}
            />
          </AdminTablePanel>

      {preview && selectedOwner ? (
        <AdminSection
          className="admin-mt-16"
          description="Preview the balance, approval, accounting impact, and audit evidence before saving this adjustment."
          statusLabel={preview ? 'No direct DB write' : 'Waiting'}
          statusTone={preview ? 'success' : 'info'}
          title="Accounting preview"
        >
          <AdminStageList>
            <PreviewFact
              helper={
                <>
                  <MoneyText amount={preview.beforeBalance} currency={currency} /> to{' '}
                  <MoneyText amount={preview.afterBalance} currency={currency} />
                </>
              }
              icon={<ShieldCheck aria-hidden="true" size={18} />}
              label="Wallet balance"
              value={<MoneyText amount={preview.walletDelta} currency={currency} />}
            />
            <PreviewFact
              helper="Manual wallet adjustment only"
              icon={<CheckCircle2 aria-hidden="true" size={18} />}
              label="Bank/Cash"
              value={preview.affects.bankCash ? 'Review required' : 'No bank/cash movement'}
            />
            <PreviewFact
              helper={
                <>
                  Platform revenue: <MoneyText amount={preview.platformRevenueAmount} currency={currency} />
                </>
              }
              icon={<CheckCircle2 aria-hidden="true" size={18} />}
              label="Output VAT"
              value={
                preview.companyOutputVat > 0 ? (
                  <MoneyText amount={preview.companyOutputVat} currency={currency} />
                ) : (
                  'No output VAT'
                )
              }
            />
            <PreviewFact
              helper={
                preview.requiresAttachment
                  ? 'Attach approval/evidence before create'
                  : 'Approval id still required'
              }
              icon={<FileWarning aria-hidden="true" size={18} />}
              label="Approval gate"
              value={preview.requiresAttachment ? 'Attachment required' : 'Attachment optional'}
            />
          </AdminStageList>
        </AdminSection>
      ) : null}

      {preview && selectedOwner ? (
        <AdminTablePanel
          description="Debit and credit legs are shown as an operator preview. No booking revenue or company VAT is created here."
          footer={
            <CreateAdjustmentForm formState={formState} preview={preview} selectedOwner={selectedOwner} />
          }
          resultLabel={preview.requiresApproval ? 'Approval required' : undefined}
          resultTone="warning"
          title="Accounting entries"
        >
          <FinanceDataTable
            emptyMessage="No accounting entries returned."
            headers={['Debit account', 'Credit account', 'Amount']}
            rowCount={preview.accountingEntries.length}
          >
            {preview.accountingEntries.map((entry) => (
              <tr key={`${entry.accountDebit}:${entry.accountCredit}:${entry.amount}`}>
                <td>
                  <strong>{formatAccountName(entry.accountDebit)}</strong>
                  <p className="muted">{entry.accountDebit}</p>
                </td>
                <td>
                  <strong>{formatAccountName(entry.accountCredit)}</strong>
                  <p className="muted">{entry.accountCredit}</p>
                </td>
                <td>
                  <MoneyText amount={entry.amount} currency={currency} />
                </td>
              </tr>
            ))}
          </FinanceDataTable>
        </AdminTablePanel>
      ) : null}
    </AdminPageTemplate>
  );
}

function WalletOwnerSearchResults({
  candidates,
  formState,
}: {
  readonly candidates: readonly AdminManualWalletAdjustmentOwnerOption[];
  readonly formState: WalletAdjustmentFormState;
}) {
  return (
    <div className="admin-mt-16">
      <h3>Matching wallet owners</h3>
      <FinanceDataTable
        emptyMessage="No customer or partner matches this search. Try a name or phone."
        headers={['Type', 'Identity', 'Account status', 'Current balance', 'Reference', 'Action']}
        rowCount={candidates.length}
      >
        {candidates.map((owner) => (
          <tr key={`${owner.ownerType}:${owner.ownerId}`}>
            <td>{owner.ownerType === 'CUSTOMER' ? 'Customer' : 'Partner'}</td>
            <td>
              <strong>{owner.displayName}</strong>
              <p className="muted">{owner.maskedPhone}</p>
            </td>
            <td>
              <StatusBadge tone={walletOwnerStatusTone(owner)}>{owner.accountStatus}</StatusBadge>
            </td>
            <td>
              <MoneyText amount={owner.currentBalance} currency={owner.currency} />
            </td>
            <td>{owner.reference}</td>
            <td>
              <AdminFormControlLink href={walletOwnerSelectionHref(owner, formState.ownerSearch)}>
                Select owner
              </AdminFormControlLink>
            </td>
          </tr>
        ))}
      </FinanceDataTable>
    </div>
  );
}

function SelectedWalletOwner({ owner }: { readonly owner: AdminManualWalletAdjustmentOwnerOption }) {
  return (
    <AdminStageList className="admin-mt-16" aria-label="Selected wallet owner">
      <PreviewFact
        helper={owner.maskedPhone}
        icon={<ShieldCheck aria-hidden="true" size={18} />}
        label={owner.displayName}
        value={owner.ownerType === 'CUSTOMER' ? 'Customer' : 'Partner'}
      />
      <PreviewFact
        helper={owner.reference}
        icon={<CheckCircle2 aria-hidden="true" size={18} />}
        label="Account status"
        value={owner.accountStatus}
      />
      <PreviewFact
        helper="Current server balance"
        icon={<CheckCircle2 aria-hidden="true" size={18} />}
        label="Wallet balance"
        value={<MoneyText amount={owner.currentBalance} currency={owner.currency} />}
      />
    </AdminStageList>
  );
}

function walletOwnerSelectionHref(owner: AdminManualWalletAdjustmentOwnerOption, ownerSearch: string) {
  return `/wallet-adjustments?${new URLSearchParams({
    intent: 'selected',
    ownerId: owner.ownerId,
    ownerSearch,
    ownerType: owner.ownerType,
  }).toString()}`;
}

function walletOwnerStatusTone(
  owner: AdminManualWalletAdjustmentOwnerOption,
): 'danger' | 'success' | 'warning' {
  if (/blocked|deleted|missing/i.test(owner.accountStatus)) return 'danger';
  if (/pending|inactive|offline/i.test(owner.accountStatus)) return 'warning';
  return 'success';
}

function AdjustmentPolicyChecklist() {
  return (
    <AdminStageList className="admin-mt-16" aria-label="Manual wallet adjustment policy gates">
      <PreviewFact
        helper="A different finance approver must review the saved request before any wallet or ledger write"
        icon={<ShieldCheck aria-hidden="true" size={18} />}
        label="Approval gate"
        value="Separate approver"
      />
      <PreviewFact
        helper="Evidence is required from 10.000.000 VND or more"
        icon={<FileWarning aria-hidden="true" size={18} />}
        label="High amount evidence"
        value="10.000.000 VND"
      />
      <PreviewFact
        helper="Receivable write-off always needs evidence"
        icon={<FileWarning aria-hidden="true" size={18} />}
        label="Tax-sensitive adjustment"
        value="Evidence"
      />
    </AdminStageList>
  );
}

function PreviewFact({
  helper,
  icon,
  label,
  value,
}: {
  readonly helper: React.ReactNode;
  readonly icon: React.ReactNode;
  readonly label: string;
  readonly value: React.ReactNode;
}) {
  return (
    <AdminStageItem>
      <span>{icon}</span>
      <div>
        <strong>{label}</strong>
        <p className="muted">{helper}</p>
      </div>
      <small>{value}</small>
    </AdminStageItem>
  );
}

function CreateAdjustmentForm({
  formState,
  preview,
  selectedOwner,
}: {
  readonly formState: WalletAdjustmentFormState;
  readonly preview: AdminManualWalletAdjustmentPreview;
  readonly selectedOwner: AdminManualWalletAdjustmentOwnerOption;
}) {
  const missingRequiredAttachment = preview.requiresAttachment && !formState.attachmentUrl;
  const bookingSettlementOnly = preview.adjustmentType === 'CASH_BOOKING_DEDUCTION';
  const blockedAccountingImpact =
    bookingSettlementOnly ||
    preview.affects.revenue ||
    preview.affects.taxPayable ||
    preview.affects.bankCash;

  return (
    <AdminFormShell action={createManualWalletAdjustment}>
      <HiddenAdjustmentInputs formState={formState} />
      <input name="idempotencyKey" type="hidden" value={randomUUID()} />
      <AdminStageList aria-label="Final wallet adjustment confirmation">
        <PreviewFact
          helper={`${selectedOwner.ownerType === 'CUSTOMER' ? 'Customer' : 'Partner'} · ${selectedOwner.maskedPhone}`}
          icon={<ShieldCheck aria-hidden="true" size={18} />}
          label={selectedOwner.displayName}
          value={selectedOwner.accountStatus}
        />
        <PreviewFact
          helper={
            <>
              <MoneyText amount={preview.beforeBalance} currency={preview.currency} /> to{' '}
              <MoneyText amount={preview.afterBalance} currency={preview.currency} />
            </>
          }
          icon={<CheckCircle2 aria-hidden="true" size={18} />}
          label={`${preview.direction === 'CREDIT' ? 'Credit' : 'Debit'} wallet`}
          value={<MoneyText amount={preview.amount} currency={preview.currency} />}
        />
        <PreviewFact
          helper={preview.reason}
          icon={<FileWarning aria-hidden="true" size={18} />}
          label="Reason and evidence"
          value={formState.attachmentUrl ? 'Evidence attached' : 'No attachment'}
        />
        <PreviewFact
          helper={preview.adjustmentType}
          icon={<ShieldCheck aria-hidden="true" size={18} />}
          label="Approval"
          value={preview.requiresApproval ? 'Separate approval required' : 'No approval required'}
        />
      </AdminStageList>
      <AdminFilterChipGroup ariaLabel="Create manual wallet adjustment gates">
        {blockedAccountingImpact ? <StatusBadge tone="danger">Blocked accounting impact</StatusBadge> : null}
        {bookingSettlementOnly ? <StatusBadge tone="danger">Use booking settlement</StatusBadge> : null}
        {missingRequiredAttachment ? <StatusBadge tone="warning">Attachment required</StatusBadge> : null}
        <AdminFormControlButton disabled={missingRequiredAttachment || blockedAccountingImpact}>
          Submit for approval
        </AdminFormControlButton>
      </AdminFilterChipGroup>
    </AdminFormShell>
  );
}

function HiddenAdjustmentInputs({ formState }: { readonly formState: WalletAdjustmentFormState }) {
  return (
    <>
      {[
        ['ownerType', formState.ownerType],
        ['ownerId', formState.ownerId],
        ['direction', formState.direction],
        ['adjustmentType', formState.adjustmentType],
        ['amount', formState.amount],
        ['reason', formState.reason],
        ['monthlyPeriod', formState.monthlyPeriod],
        ['attachmentUrl', formState.attachmentUrl],
        ['ownerSearch', formState.ownerSearch],
      ].map(([name, value]) => (
        <input key={name} name={name} type="hidden" value={value} />
      ))}
    </>
  );
}

async function fetchWalletAdjustmentOwners(formState: WalletAdjustmentFormState) {
  const query = formState.ownerSearch;
  if (query.length < 2) {
    return [];
  }
  const params = new URLSearchParams({ ownerType: formState.ownerType, q: query, take: '10' });
  return adminGet<AdminManualWalletAdjustmentOwnerOption[]>(
    `/admin/wallet-adjustments/owners?${params.toString()}`,
    [],
  );
}

async function fetchPreview(formState: WalletAdjustmentFormState) {
  if (!formState.ownerId || !formState.amount || !formState.reason) {
    return null;
  }

  return adminPost<AdminManualWalletAdjustmentPreview | null>(
    '/admin/wallet-adjustments/preview',
    {
      adjustmentType: formState.adjustmentType,
      amount: Number(formState.amount),
      ...(formState.attachmentUrl ? { attachmentUrl: formState.attachmentUrl } : {}),
      direction: formState.direction,
      ...(formState.monthlyPeriod ? { monthlyPeriod: formState.monthlyPeriod } : {}),
      ownerId: formState.ownerId,
      ownerType: formState.ownerType,
      reason: formState.reason,
    },
    null,
  );
}

async function fetchAdjustmentHistory(
  formState: WalletAdjustmentFormState,
  historyFilters: WalletAdjustmentHistoryFilters,
) {
  return adminGet<AdminManualWalletAdjustmentRow[]>(
    buildAdjustmentHistoryHref(formState, historyFilters),
    [],
  );
}

async function fetchAdjustmentHistorySummary(
  formState: WalletAdjustmentFormState,
  historyFilters: WalletAdjustmentHistoryFilters,
) {
  return adminGet<AdminManualWalletAdjustmentSummary>(
    buildAdjustmentHistorySummaryHref(formState, historyFilters),
    { total: 0 },
  );
}

async function fetchAdjustmentRequestHistory(
  formState: WalletAdjustmentFormState,
  filters: WalletAdjustmentRequestHistoryFilters,
) {
  return adminGet<AdminManualWalletAdjustmentRequest[]>(
    buildAdjustmentRequestHistoryHref(formState, filters),
    [],
  );
}

async function fetchAdjustmentRequestHistorySummary(
  formState: WalletAdjustmentFormState,
  filters: WalletAdjustmentRequestHistoryFilters,
) {
  return adminGet<AdminManualWalletAdjustmentSummary>(
    buildAdjustmentRequestHistorySummaryHref(formState, filters),
    { total: 0 },
  );
}

function buildAdjustmentRequestHistoryHref(
  formState: WalletAdjustmentFormState,
  filters: WalletAdjustmentRequestHistoryFilters,
) {
  const params = walletAdjustmentRequestHistoryApiParams(formState, filters);
  params.set('take', String(filters.pageSize));
  const skip = (filters.page - 1) * filters.pageSize;
  if (skip > 0) {
    params.set('skip', String(skip));
  }
  return `/admin/wallet-adjustment-requests?${params.toString()}`;
}

function buildAdjustmentRequestHistorySummaryHref(
  formState: WalletAdjustmentFormState,
  filters: WalletAdjustmentRequestHistoryFilters,
) {
  const query = walletAdjustmentRequestHistoryApiParams(formState, filters).toString();
  return query
    ? `/admin/wallet-adjustment-requests/summary?${query}`
    : '/admin/wallet-adjustment-requests/summary';
}

function walletAdjustmentRequestHistoryApiParams(
  formState: WalletAdjustmentFormState,
  filters: WalletAdjustmentRequestHistoryFilters,
) {
  const params = new URLSearchParams();
  if (filters.status) {
    params.set('status', filters.status);
  }
  const ownerType = walletAdjustmentRequestHistoryOwnerType(formState, filters);
  if (ownerType) {
    params.set('ownerType', ownerType);
  }
  if (formState.ownerId) {
    params.set('ownerId', formState.ownerId);
    if (formState.ownerSearch) params.set('ownerSearch', formState.ownerSearch);
  }
  return params;
}

function buildAdjustmentHistoryHref(
  formState: WalletAdjustmentFormState,
  historyFilters: WalletAdjustmentHistoryFilters,
) {
  const params = new URLSearchParams();
  const ownerType = walletAdjustmentHistoryOwnerType(formState, historyFilters);
  if (ownerType) {
    params.set('ownerType', ownerType);
  }
  if (formState.ownerId) {
    params.set('ownerId', formState.ownerId);
    if (formState.ownerSearch) params.set('ownerSearch', formState.ownerSearch);
  }
  params.set('take', String(historyFilters.pageSize));
  const skip = (historyFilters.page - 1) * historyFilters.pageSize;
  if (skip > 0) {
    params.set('skip', String(skip));
  }
  return `/admin/wallet-adjustments?${params.toString()}`;
}

function buildAdjustmentHistorySummaryHref(
  formState: WalletAdjustmentFormState,
  historyFilters: WalletAdjustmentHistoryFilters,
) {
  const params = new URLSearchParams();
  const ownerType = walletAdjustmentHistoryOwnerType(formState, historyFilters);
  if (ownerType) {
    params.set('ownerType', ownerType);
  }
  if (formState.ownerId) {
    params.set('ownerId', formState.ownerId);
  }
  const query = params.toString();
  return query ? `/admin/wallet-adjustments/summary?${query}` : '/admin/wallet-adjustments/summary';
}

type WalletAdjustmentHistoryFilters = {
  readonly ownerType: AdminManualWalletAdjustmentOwnerType | null;
  readonly page: number;
  readonly pageSize: number;
};

type WalletAdjustmentRequestHistoryFilters = {
  readonly ownerType: AdminManualWalletAdjustmentOwnerType | null;
  readonly page: number;
  readonly pageSize: number;
  readonly status: AdminManualWalletAdjustmentRequestStatus | null;
};

type WalletAdjustmentFormState = {
  readonly adjustmentType: AdminManualWalletAdjustmentType;
  readonly amount: string;
  readonly attachmentUrl: string;
  readonly direction: AdminManualWalletAdjustmentDirection;
  readonly intent: string;
  readonly monthlyPeriod: string;
  readonly ownerId: string;
  readonly ownerSearch: string;
  readonly ownerType: AdminManualWalletAdjustmentOwnerType;
  readonly reason: string;
};

function readWalletAdjustmentFormState(
  params: Record<string, string | string[] | undefined>,
): WalletAdjustmentFormState {
  return {
    adjustmentType: readParam(params, 'adjustmentType', 'PARTNER_BONUS') as AdminManualWalletAdjustmentType,
    amount: readParam(params, 'amount'),
    attachmentUrl: readParam(params, 'attachmentUrl'),
    direction: readParam(params, 'direction', 'CREDIT') as AdminManualWalletAdjustmentDirection,
    intent: readParam(params, 'intent'),
    monthlyPeriod: readParam(params, 'monthlyPeriod'),
    ownerId: readParam(params, 'ownerId'),
    ownerSearch: readParam(params, 'ownerSearch'),
    ownerType: readParam(params, 'ownerType', 'PARTNER') as AdminManualWalletAdjustmentOwnerType,
    reason: readParam(params, 'reason'),
  };
}

function readWalletAdjustmentHistoryFilters(
  params: Record<string, string | string[] | undefined>,
): WalletAdjustmentHistoryFilters {
  const ownerType = readParam(params, 'ownerType');
  return {
    ownerType: ownerOptions.some((option) => option.value === ownerType)
      ? (ownerType as AdminManualWalletAdjustmentOwnerType)
      : null,
    page: readPositiveIntParam(params, 'page', 1),
    pageSize: Math.min(
      readPositiveIntParam(params, 'pageSize', WALLET_ADJUSTMENT_HISTORY_TAKE),
      WALLET_ADJUSTMENT_HISTORY_MAX_TAKE,
    ),
  };
}

function readWalletAdjustmentRequestHistoryFilters(
  params: Record<string, string | string[] | undefined>,
): WalletAdjustmentRequestHistoryFilters {
  const status = readParam(params, 'requestStatus');
  const ownerType = readParam(params, 'ownerType');
  return {
    ownerType: ownerOptions.some((option) => option.value === ownerType)
      ? (ownerType as AdminManualWalletAdjustmentOwnerType)
      : null,
    page: readPositiveIntParam(params, 'requestPage', 1),
    pageSize: Math.min(
      readPositiveIntParam(params, 'requestPageSize', WALLET_ADJUSTMENT_REQUEST_HISTORY_TAKE),
      WALLET_ADJUSTMENT_REQUEST_HISTORY_MAX_TAKE,
    ),
    status: requestStatusOptions.some((option) => option.value === status)
      ? (status as AdminManualWalletAdjustmentRequestStatus)
      : null,
  };
}

function buildWalletAdjustmentHistoryPagination(
  rows: readonly AdminManualWalletAdjustmentRow[],
  filters: WalletAdjustmentHistoryFilters,
  totalRows: number,
) {
  const safeTotalRows = Number.isFinite(totalRows) ? Math.max(0, Math.trunc(totalRows)) : 0;
  const totalPages = Math.max(1, Math.ceil(safeTotalRows / filters.pageSize));
  const page = Math.min(filters.page, totalPages);
  const start = (page - 1) * filters.pageSize;

  return {
    from: rows.length === 0 ? 0 : start + 1,
    page,
    pageSize: filters.pageSize,
    rows,
    to: rows.length === 0 ? 0 : Math.min(start + rows.length, safeTotalRows),
    totalPages,
    totalRows: safeTotalRows,
  };
}

function buildWalletAdjustmentRequestHistoryPagination(
  rows: readonly AdminManualWalletAdjustmentRequest[],
  filters: WalletAdjustmentRequestHistoryFilters,
  totalRows: number,
) {
  const safeTotalRows = Number.isFinite(totalRows) ? Math.max(0, Math.trunc(totalRows)) : 0;
  const totalPages = Math.max(1, Math.ceil(safeTotalRows / filters.pageSize));
  const page = Math.min(filters.page, totalPages);
  const start = (page - 1) * filters.pageSize;

  return {
    from: rows.length === 0 ? 0 : start + 1,
    page,
    pageSize: filters.pageSize,
    rows,
    to: rows.length === 0 ? 0 : Math.min(start + rows.length, safeTotalRows),
    totalPages,
    totalRows: safeTotalRows,
  };
}

function walletAdjustmentSummaryTotal(summary: AdminManualWalletAdjustmentSummary) {
  return typeof summary.total === 'number' && Number.isFinite(summary.total)
    ? Math.max(0, Math.trunc(summary.total))
    : 0;
}

function walletAdjustmentHistoryPageHref(
  formState: WalletAdjustmentFormState,
  filters: WalletAdjustmentHistoryFilters,
  page: number,
) {
  const params = new URLSearchParams({ view: 'records' });
  const ownerType = walletAdjustmentHistoryOwnerType(formState, filters);
  if (ownerType) {
    params.set('ownerType', ownerType);
  }
  if (formState.ownerId) {
    params.set('ownerId', formState.ownerId);
  }
  if (filters.pageSize !== WALLET_ADJUSTMENT_HISTORY_TAKE) {
    params.set('pageSize', String(filters.pageSize));
  }
  if (page > 1) {
    params.set('page', String(page));
  }
  return `/wallet-adjustments?${params.toString()}`;
}

function walletAdjustmentRequestHistoryPageHref(
  formState: WalletAdjustmentFormState,
  historyFilters: WalletAdjustmentHistoryFilters,
  requestFilters: WalletAdjustmentRequestHistoryFilters,
  page: number,
) {
  const params = new URLSearchParams({ view: 'requests' });
  const ownerType = walletAdjustmentRequestHistoryOwnerType(formState, requestFilters);
  if (ownerType) {
    params.set('ownerType', ownerType);
  }
  if (formState.ownerId) {
    params.set('ownerId', formState.ownerId);
  }
  if (requestFilters.status) {
    params.set('requestStatus', requestFilters.status);
  }
  if (requestFilters.pageSize !== WALLET_ADJUSTMENT_REQUEST_HISTORY_TAKE) {
    params.set('requestPageSize', String(requestFilters.pageSize));
  }
  if (page > 1) {
    params.set('requestPage', String(page));
  }
  if (historyFilters.pageSize !== WALLET_ADJUSTMENT_HISTORY_TAKE) {
    params.set('pageSize', String(historyFilters.pageSize));
  }
  if (historyFilters.page > 1) {
    params.set('page', String(historyFilters.page));
  }
  return `/wallet-adjustments?${params.toString()}`;
}

function walletAdjustmentRequestLabels(
  formState: WalletAdjustmentFormState,
  selectedOwner?: AdminManualWalletAdjustmentOwnerOption,
) {
  const labels = [
    `Owner: ${optionLabel(ownerOptions, formState.ownerType)}`,
    `Direction: ${optionLabel(directionOptions, formState.direction)}`,
    `Type: ${optionLabel(adjustmentTypeOptions, formState.adjustmentType)}`,
  ];

  if (selectedOwner) labels.push(`Target: ${selectedOwner.reference}`);
  if (formState.amount) {
    labels.push(`Amount: ${formState.amount} VND`);
  }
  if (formState.monthlyPeriod) {
    labels.push(`Period: ${formState.monthlyPeriod}`);
  }

  return labels;
}

function walletAdjustmentRecordFilterLabels(
  formState: WalletAdjustmentFormState,
  historyFilters: WalletAdjustmentHistoryFilters,
) {
  const ownerType = walletAdjustmentHistoryOwnerType(formState, historyFilters);
  const ownerLabel = ownerType ? optionLabel(ownerOptions, ownerType) : 'All wallet owners';
  return [`Owner: ${ownerLabel}`, `Rows per page: ${historyFilters.pageSize}`];
}

function walletAdjustmentRequestHistoryFilterLabels(
  formState: WalletAdjustmentFormState,
  requestFilters: WalletAdjustmentRequestHistoryFilters,
) {
  const ownerType = walletAdjustmentRequestHistoryOwnerType(formState, requestFilters);
  return [
    `Status: ${optionLabel(requestStatusOptions, requestFilters.status ?? '')}`,
    `Owner: ${ownerType ? optionLabel(ownerOptions, ownerType) : 'All wallet owners'}`,
    `Rows per page: ${requestFilters.pageSize}`,
  ];
}

function walletAdjustmentHistoryOwnerType(
  formState: WalletAdjustmentFormState,
  historyFilters: WalletAdjustmentHistoryFilters,
) {
  return historyFilters.ownerType ?? (formState.ownerId ? formState.ownerType : null);
}

function walletAdjustmentRequestHistoryOwnerType(
  formState: WalletAdjustmentFormState,
  filters: WalletAdjustmentRequestHistoryFilters,
) {
  return filters.ownerType ?? (formState.ownerId ? formState.ownerType : null);
}

function walletAdjustmentRequestStatusLabel(status?: AdminManualWalletAdjustmentRequestStatus) {
  switch (status) {
    case 'EXECUTED':
      return 'Executed';
    case 'REJECTED':
      return 'Rejected';
    case 'CANCELLED':
      return 'Cancelled';
    default:
      return 'Pending approval';
  }
}

function walletAdjustmentRequestStatusTone(
  status?: AdminManualWalletAdjustmentRequestStatus,
): 'danger' | 'neutral' | 'success' | 'warning' {
  switch (status) {
    case 'EXECUTED':
      return 'success';
    case 'REJECTED':
      return 'danger';
    case 'CANCELLED':
      return 'neutral';
    default:
      return 'warning';
  }
}

function walletAdjustmentRequestOperatorLines(
  request: AdminManualWalletAdjustmentRequest,
): AdminFinanceOperatorEvidenceLine[] {
  const lines: AdminFinanceOperatorEvidenceLine[] = [
    {
      fallbackId: request.requestedByAdminId,
      key: 'requested-by',
      label: 'Requested by',
      operator: request.requestedBy,
    },
  ];

  if (request.status === 'EXECUTED') {
    lines.push({
      fallbackId: request.approvedByAdminId,
      key: 'approved-by',
      label: 'Approved by',
      operator: request.approvedBy,
    });
  } else if (request.status === 'REJECTED') {
    lines.push({
      fallbackId: request.rejectedByAdminId,
      key: 'rejected-by',
      label: 'Rejected by',
      operator: request.rejectedBy,
    });
  } else if (request.status === 'CANCELLED') {
    lines.push({
      fallbackId: request.requestedByAdminId,
      key: 'cancelled-by',
      label: 'Cancelled by',
      operator: request.requestedBy,
    });
  }

  return lines;
}

function walletOwnerDetailHref(ownerType: AdminManualWalletAdjustmentOwnerType, ownerId: string) {
  const encodedOwnerId = encodeURIComponent(ownerId);
  return ownerType === 'CUSTOMER' ? `/customers/${encodedOwnerId}` : `/partners/${encodedOwnerId}`;
}

function optionLabel<Value extends string>(
  options: readonly { readonly label: string; readonly value: Value }[],
  value: Value,
) {
  return options.find((option) => option.value === value)?.label ?? value;
}

function readParam(params: Record<string, string | string[] | undefined>, key: string, fallback = '') {
  const value = params[key];
  return Array.isArray(value) ? (value[0] ?? fallback) : (value ?? fallback);
}

function readPositiveIntParam(
  params: Record<string, string | string[] | undefined>,
  key: string,
  fallback: number,
) {
  const value = Number.parseInt(readParam(params, key), 10);
  return Number.isFinite(value) && value > 0 ? Math.trunc(value) : fallback;
}

function formatAccountName(value: string) {
  return value
    .split('_')
    .map((part) => `${part.slice(0, 1).toUpperCase()}${part.slice(1)}`)
    .join(' ');
}

function formatBalanceChange(row: AdminManualWalletAdjustmentRow) {
  if (typeof row.beforeBalance !== 'number' || typeof row.afterBalance !== 'number') {
    return 'Balance preview unavailable';
  }

  return (
    <>
      <MoneyText amount={row.beforeBalance} currency={row.currency} /> -&gt;{' '}
      <MoneyText amount={row.afterBalance} currency={row.currency} />
    </>
  );
}

function walletImpactLabel(row: AdminManualWalletAdjustmentRow) {
  const impacts = [
    row.affects?.walletLiability ? 'wallet liability' : null,
    row.affects?.partnerReceivable ? 'partner receivable' : null,
    row.affects?.expense ? 'expense' : null,
    row.affects?.revenue ? 'revenue review' : null,
    row.affects?.taxPayable ? 'tax review' : null,
  ].filter(Boolean);

  return impacts.length > 0 ? impacts.join(', ') : 'No accounting impact metadata';
}

function walletAdjustmentNotice(notice: string) {
  if (notice === 'requested') {
    return {
      badge: 'Pending',
      detail:
        'The request is stored in Finance Approval Queue. No wallet or accounting ledger has been written yet.',
      title: 'Manual adjustment submitted',
      tone: 'success' as const,
    };
  }

  if (notice === 'created') {
    return {
      badge: 'Saved',
      detail: 'Wallet impact and admin audit log were written through the Admin API.',
      title: 'Manual adjustment created',
      tone: 'success' as const,
    };
  }

  if (notice === 'admin-auth') {
    return {
      badge: 'Auth',
      detail: 'Admin API credentials are missing or expired. Refresh the admin session before trying again.',
      title: 'Manual adjustment was not saved',
      tone: 'danger' as const,
    };
  }

  if (notice === 'failed') {
    return {
      badge: 'Blocked',
      detail: 'No approval request was saved. Check owner id, attachment, and closed-period rules.',
      title: 'Manual adjustment request was not saved',
      tone: 'danger' as const,
    };
  }

  if (notice === 'attachment-required') {
    return {
      badge: 'Evidence',
      detail:
        'No wallet impact record was saved. High amount adjustments and receivable write-offs need an attachment URL.',
      title: 'Attachment evidence is required',
      tone: 'danger' as const,
    };
  }

  if (notice === 'attachment-invalid') {
    return {
      badge: 'Evidence',
      detail: 'No wallet impact record was saved. Attachment evidence must be a valid http or https URL.',
      title: 'Attachment URL is invalid',
      tone: 'danger' as const,
    };
  }

  if (notice === 'monthly-period-invalid') {
    return {
      badge: 'Period',
      detail:
        'No wallet impact record was saved. Monthly period must use YYYY-MM before finance can save it.',
      title: 'Monthly period is invalid',
      tone: 'danger' as const,
    };
  }

  if (notice === 'settlement-required') {
    return {
      badge: 'Settlement',
      detail:
        'No wallet impact record was saved. Cash booking deductions must use booking settlement logic so revenue and tax are calculated correctly.',
      title: 'Use booking settlement instead',
      tone: 'danger' as const,
    };
  }

  return null;
}
